const browseRoutes={drinks:[[0,7.4],[0,5.15],[2.1,5.15],[2.1,-.8],[-4,-.8]],fruit:[[0,7.4],[0,5.15],[2.1,5.15],[2.1,3.2],[-4,3.2]],grocery:[[0,7.4],[0,5.15],[2.1,5.15],[2.1,-.8],[0,-.8]],dairy:[[0,7.4],[0,5.15],[2.1,5.15],[2.1,-1.8],[5.8,-1.8]]};const paths={basket:[[2.4,8]],entering:[[0,7.4],[0,5.15],[2.1,5.15],[2.1,2.9],[2.1,.1]],toCheckout:[[2.1,.1],[2.1,3],[2.1,5.15],[4.65,5.15]],leaving:[[2.1,5.15],[0,5.15],[0,7.4],[7,8.3]],rejected:[[2.1,2.9],[2.1,5.15],[0,5.15],[0,7.4],[7,8.3]]};function walkCustomer(c,dt){if(c.stage==='basket'||c.stage==='entering'||c.stage==='toCheckout'||c.stage==='leaving'||c.stage==='rejected'){let path=paths[c.stage];if(c.stage==='entering')path=browseRoutes[c.browseCategory]||browseRoutes.grocery;if(c.stage==='toCheckout'){let shelfPoint=(browseRoutes[c.browseCategory]||browseRoutes.grocery).at(-1);path=[[shelfPoint[0],shelfPoint[1]],[2.1,shelfPoint[1]],[2.1,5.15],[4.65,5.15]]}if(c.stage==='rejected'){let shelfPoint=(browseRoutes[c.browseCategory]||browseRoutes.grocery).at(-1);path=[[shelfPoint[0],shelfPoint[1]],[2.1,shelfPoint[1]],[2.1,5.15],[0,5.15],[0,7.4],[7,8.3]]}let way=path[c.pathIndex]||path[path.length-1];if(c.stage==='toCheckout'&&c.pathIndex===path.length-1){let slot=s.customers.filter(n=>['checkout','toCheckout'].includes(n.stage)&&n.id<c.id).length;way=[4.65-slot*.72,5.12]}if((c.stage==='entering'||c.stage==='leaving'||c.stage==='rejected')&&!s.door&&c.pathIndex>=0&&Math.abs(c.x)<.7&&c.z>5.65&&c.z<6.5)return false;let dx=way[0]-c.x,dz=way[1]-c.z,d=Math.hypot(dx,dz);if(d<.08){c.pathIndex++;if(c.pathIndex>=path.length){c.pathIndex=0;if(c.stage==='basket'){c.hasBasket=true;c.stage='entering'}else if(c.stage==='entering')c.stage='browsing';else if(c.stage==='toCheckout')c.stage='checkout';else c.stage='done'}return false}let step=Math.min(d,dt*(c.walkSpeed||1.2));c.x+=dx/d*step;c.z+=dz/d*step;c.angle=Math.atan2(dx,dz);return true}return false}
